from deppy import dependent, Type, Nat, Z, S, Eq, refl, Sigma, Pair, Vec, VNil


# Basics: @dependent functions are checked statically; their bodies are not
# executed as ordinary Python to establish a proof.
# Nat has constructors Z() = 0 and S(n) = n + 1.


@dependent
def identity[A: Type](x: A) -> A:
    # The same implementation works for any type A: x ↦ x.
    return x


@dependent
def twice(n: Nat) -> Nat:
    # Local names can carry explicit types or have their types inferred.
    first: Nat = S(n)
    second = S(first)
    return identity(second)


@dependent
def reflexive(n: Nat) -> Eq[Nat, n, n]:
    # Eq[Nat, n, n] states n = n; refl(n) is its proof.
    proof = refl(n)
    return proof


@dependent
def empty(n: Nat) -> Vec[Nat, Z()]:
    # VNil() is a vector with length 0, regardless of n.
    return VNil()


@dependent
def pack[T: Type](n: Nat, xs: Vec[T, n]) -> Sigma[Nat, lambda k: Vec[T, k]]:
    # A dependent pair stores k together with a vector of length k.
    return Pair(n, xs)


@dependent
def identity_zero() -> Eq[Nat, identity(Z()), Z()]:
    # A checked equality, rather than a Python assert: identity(0) = 0.
    return refl(Z())

proof_equality.source:
from deppy import dependent, Nat, Eq, refl, sym, trans, cong, S


# Part 1: equality proofs. Eq[Nat, a, b] means a = b for natural numbers.
# Each function returns a proof term; the checker verifies its stated type.


@dependent
def same(n: Nat) -> Eq[Nat, n, n]:
    # Reflexivity: ∀n, n = n.
    return refl(n)


@dependent
def turn_around(n: Nat, m: Nat, proof: Eq[Nat, n, m]) -> Eq[Nat, m, n]:
    # Symmetry: n = m → m = n.
    return sym(proof)


@dependent
def chain(n: Nat, m: Nat, k: Nat, first: Eq[Nat, n, m], second: Eq[Nat, m, k]) -> Eq[Nat, n, k]:
    # Transitivity: n = m ∧ m = k → n = k.
    return trans(first, second)


@dependent
def successor_preserves(n: Nat, m: Nat, proof: Eq[Nat, n, m]) -> Eq[Nat, S(n), S(m)]:
    # Congruence: n = m → S(n) = S(m).
    return cong(S, proof)

